class Solution {
public:
    string largestTimeFromDigits(vector<int>& arr) {
        int best = -1;
        sort(arr.begin(), arr.end());
        do {
            int hh = arr[0] * 10 + arr[1];
            int mm = arr[2] * 10 + arr[3];
            if (hh <= 23 && mm <= 59) {
                int total = hh * 60 + mm;
                if (total > best) best = total;
            }
        } while (next_permutation(arr.begin(), arr.end()));
        if (best < 0) return "";
        int hh = best / 60;
        int mm = best % 60;
        string res;
        res += char('0' + hh / 10);
        res += char('0' + hh % 10);
        res += ':';
        res += char('0' + mm / 10);
        res += char('0' + mm % 10);
        return res;
    }
};
